tool_input.command:
node -e '
const fs=require("fs"),cp=require("child_process");
const run=(args)=>{const r=cp.spawnSync("node",["scripts/merge-parts.js",...args],{encoding:"utf8"});console.log("> "+args.join(" ")+"\n  exit="+r.status+"\n"+(r.stdout+r.stderr).replace(/^/gm,"  "));return r;};
// 1) 正常系: 部品がそのまま含まれているか
let r=run(["--title","テスト","--dir","tmp-merge-test"]);
const out=fs.readFileSync("tmp-merge-test/output/index.html","utf8");
for(const n of ["body.html","style.css","script.js"]) console.log("  includes "+n+":", out.includes(fs.readFileSync("tmp-merge-test/parts/"+n,"utf8")));
// 2) --title なし
run(["--dir","tmp-merge-test"]);
// 3) 部品不足（script.js を一時退避）
fs.renameSync("tmp-merge-test/parts/script.js","tmp-merge-test/parts/script.js.bak");
run(["--title","テスト","--dir","tmp-merge-test"]);
fs.renameSync("tmp-merge-test/parts/script.js.bak","tmp-merge-test/parts/script.js");
// 4) parts フォルダ自体がない + title なし
run(["--dir","tmp-merge-test-nonexistent"]);
// 5) 警告: body.html に禁止タグ、--out と --lang 指定
fs.mkdirSync("tmp-merge-test/warn/parts",{recursive:true});
fs.writeFileSync("tmp-merge-test/warn/parts/body.html","<body><style>p{}</style><p>x</p><script>1</script></body>");
fs.copyFileSync("tmp-merge-test/parts/style.css","tmp-merge-test/warn/parts/style.css");
fs.copyFileSync("tmp-merge-test/parts/script.js","tmp-merge-test/warn/parts/script.js");
run(["--title","A & <B>","--lang","en","--dir","tmp-merge-test/warn","--out","tmp-merge-test/custom/out/page.html"]);
console.log("  head of custom out:\n"+fs.readFileSync("tmp-merge-test/custom/out/page.html","utf8").split("\n").slice(0,6).join("\n").replace(/^/gm,"    "));
'
